import re

class Solution:
    def expand(self, pattern: str) -> str:
        inner = re.compile(r"(\d+)\[([a-z]*)\]")
        while "[" in pattern:
            m = inner.search(pattern)
            pattern = pattern[:m.start()] + m.group(2) * int(m.group(1)) + pattern[m.end():]
        return pattern

