class Solution {
    public String expand(String pattern) {
        java.util.regex.Pattern inner = java.util.regex.Pattern.compile("(\\d+)\\[([a-z]*)\\]");
        while (pattern.indexOf('[') >= 0) {
            java.util.regex.Matcher m = inner.matcher(pattern);
            m.find();
            String body = m.group(2).repeat(Integer.parseInt(m.group(1)));
            pattern = pattern.substring(0, m.start()) + body + pattern.substring(m.end());
        }
        return pattern;
    }
}

