class Solution {
public:
    string expand(string& pattern) {
        string t = pattern;
        while (t.find('[') != string::npos) {
            size_t close = t.find(']');
            size_t open = t.rfind('[', close);
            size_t start = open;
            while (start > 0 && isdigit(t[start - 1])) start--;
            int k = stoi(t.substr(start, open - start));
            string body = t.substr(open + 1, close - open - 1), rep;
            for (int i = 0; i < k; i++) rep += body;
            t = t.substr(0, start) + rep + t.substr(close + 1);
        }
        return t;
    }
};

