    char* t = malloc(cap);
    strcpy(t, pattern);
    char* close;
    while ((close = strchr(t, ']')) != NULL) {
        char* open = close;
        while (*open != '[') open--;
        char* start = open;
        while (start > t && start[-1] >= '0' && start[-1] <= '9') start--;
        int k = atoi(start);
        int bodyLen = close - open - 1, before = start - t, after = strlen(close + 1);
        int need = before + k * bodyLen + after + 1;
        char* u = malloc(need);
        memcpy(u, t, before);
        for (int i = 0; i < k; i++) memcpy(u + before + i * bodyLen, open + 1, bodyLen);
        memcpy(u + before + k * bodyLen, close + 1, after + 1);
        free(t);
        t = u;
    }
