class Solution {
    private String p;
    private int i;

    public String expand(String pattern) {
        p = pattern;
        i = 0;
        return parse();
    }

    private String parse() {
        StringBuilder out = new StringBuilder();
        while (i < p.length() && p.charAt(i) != ']') {
            char c = p.charAt(i);
            if (Character.isDigit(c)) {
                int k = 0;
                while (Character.isDigit(p.charAt(i))) k = k * 10 + (p.charAt(i++) - '0');
                i++;
                String inner = parse();
                i++;
                out.append(inner.repeat(k));
            } else {
                out.append(c);
                i++;
            }
        }
        return out.toString();
    }
}

