typedef struct { char* s; int len, cap; } Buf;

static void put(Buf* b, const char* src, int n) {
    if (b->len + n + 1 > b->cap) {
        while (b->len + n + 1 > b->cap) b->cap *= 2;
        b->s = realloc(b->s, b->cap);
    }
    memcpy(b->s + b->len, src, n);
    b->len += n;
}

static Buf parse(const char* p, int* i) {
    Buf out = {malloc(16), 0, 16};
    while (p[*i] && p[*i] != ']') {
        if (p[*i] >= '0' && p[*i] <= '9') {
            int k = 0;
            while (p[*i] >= '0' && p[*i] <= '9') k = k * 10 + (p[(*i)++] - '0');
            (*i)++;
            Buf inner = parse(p, i);
            (*i)++;
            for (int r = 0; r < k; r++) put(&out, inner.s, inner.len);
            free(inner.s);
        } else {
            put(&out, p + *i, 1);
            (*i)++;
        }
    }
    out.s[out.len] = '\0';
    return out;
}

char* expand(char* pattern) {
    int i = 0;
    return parse(pattern, &i).s;
}

