class Solution {
public:
    string expand(string& pattern) {
        vector<pair<string, int>> stack;
        string cur;
        int num = 0;
        for (char c : pattern) {
            if (isdigit(c)) num = num * 10 + (c - '0');
            else if (c == '[') {
                stack.push_back({cur, num});
                cur.clear();
                num = 0;
            } else if (c == ']') {
                auto [prev, k] = stack.back();
                stack.pop_back();
                for (int r = 0; r < k; r++) prev += cur;
                cur = prev;
            } else cur += c;
        }
        return cur;
    }
};

