char* expand(char* pattern) {
    int cap = 1 << 17;
    char* out = malloc(cap);
    int len = 0, top = 0, num = 0;
    int* startAt = malloc(strlen(pattern) * sizeof(int) + sizeof(int));
    int* times = malloc(strlen(pattern) * sizeof(int) + sizeof(int));
    for (char* p = pattern; *p; p++) {
        if (*p >= '0' && *p <= '9') num = num * 10 + (*p - '0');
        else if (*p == '[') {
            startAt[top] = len;
            times[top++] = num;
            num = 0;
        } else if (*p == ']') {
            int start = startAt[--top], body = len - start;
            for (int r = 1; r < times[top]; r++) {
                memcpy(out + len, out + start, body);
                len += body;
            }
        } else out[len++] = *p;
    }
    out[len] = '\0';
    free(startAt);
    free(times);
    return out;
}
